        except subprocess.TimeoutExpired:
            out = ""
        good = out.strip() == extra["expect"].strip()
        print(f"  repaired behaviour: {'ok' if good else 'wrong'}")
        ok += 1 if good else 0
    finish(ok / total)


if __name__ == "__main__":
    main()

